from pathlib import Path
p=Path('semana 9')
(p/'validation.js').write_text('''export const MAX=5*1024*1024;
export const TYPES=['image/jpeg','image/png','image/webp'];
export function validUpload(v){return v && typeof v.filename==='string' && v.filename.length>0 && v.filename.length<=180 && TYPES.includes(v.contentType) && Number.isSafeInteger(v.sizeBytes) && v.sizeBytes>0 && v.sizeBytes<MAX;}
export function validKey(k){return typeof k==='string' && k.startsWith('originales/') && !k.includes('..') && !k.includes('\\\\') && !k.endsWith('/') && k.length<1024;}
export function magic(b,t){return t==='image/jpeg'?b[0]===255&&b[1]===216&&b[2]===255:t==='image/png'?b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):t==='image/webp'?b.toString('ascii',0,4)==='RIFF'&&b.toString('ascii',8,12)==='WEBP':false;}
''',encoding='utf8')
(p/'server.js').write_text('''import express from 'express';
import {existsSync} from 'node:fs';
import {randomUUID} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {S3Client,PutObjectCommand,GetObjectCommand,HeadObjectCommand,DeleteObjectCommand,ListObjectsV2Command} from '@aws-sdk/client-s3';
import {getSignedUrl} from '@aws-sdk/s3-request-presigner';
import {MAX,TYPES,validUpload,validKey,magic} from './validation.js';
const root=fileURLToPath(new URL('.',import.meta.url));
if(existsSync(root+'.env'))process.loadEnvFile(root+'.env');
const bucket=process.env.S3_BUCKET,region=process.env.AWS_REGION||'us-east-1',port=Number(process.env.PORT||3009),origin=process.env.APP_URL||`http://localhost:${port}`;
const s3=new S3Client({region,requestChecksumCalculation:'WHEN_REQUIRED'});
const app=express();app.disable('x-powered-by');app.use(express.json({limit:'12kb'}));
app.use((req,res,next)=>{res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Referrer-Policy','no-referrer');res.setHeader('Content-Security-Policy',"default-src 'self'; img-src 'self' blob: data: https://*.amazonaws.com; connect-src 'self' https://*.amazonaws.com; style-src 'self'; script-src 'self'; frame-ancestors 'none'; object-src 'none'");if(req.path.startsWith('/api'))res.setHeader('Cache-Control','no-store');if(!['GET','HEAD'].includes(req.method)&&req.get('origin')&&req.get('origin')!==origin)return res.status(403).json({error:'Origen no permitido.'});next();});
const limits=new Map();app.use('/api',(req,res,next)=>{if(req.method==='GET')return next();const now=Date.now();for(const[k,v]of limits)if(v.until<now)limits.delete(k);let v=limits.get(req.ip)||{n:0,until:now+60000};limits.set(req.ip,v);if(++v.n>30)return res.status(429).json({error:'Demasiadas solicitudes. Espera un minuto.'});next();});
const pending=new Map();setInterval(()=>{for(const[k,v]of pending)if(v.expires<Date.now())pending.delete(k);},60000).unref();
app.get('/api/status',(req,res)=>res.json({bucket,region,maxBytes:MAX,types:TYPES,uploadSeconds:300,viewSeconds:900}));
app.post('/api/upload-url',async(req,res)=>{if(!validUpload(req.body))return res.status(400).json({error:'Selecciona una imagen JPG, PNG o WebP de menos de 5 MB.'});const {filename,contentType,sizeBytes}=req.body;const key=`originales/${randomUUID()}-${filename.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const ticket=randomUUID();pending.set(ticket,{key,contentType,sizeBytes,expires:Date.now()+600000});const uploadUrl=await getSignedUrl(s3,new PutObjectCommand({Bucket:bucket,Key:key,ContentType:contentType,ContentLength:sizeBytes,ServerSideEncryption:'AES256'}),{expiresIn:300,signableHeaders:new Set(['content-type','content-length'])});res.json({uploadUrl,key,ticket,headers:{'Content-Type':contentType},expiresIn:300});});
app.post('/api/uploads/complete',async(req,res)=>{const t=pending.get(req.body?.ticket);if(!t||t.expires<Date.now())return res.status(400).json({error:'La validación de carga venció. Vuelve a intentarlo.'});const head=await s3.send(new HeadObjectCommand({Bucket:bucket,Key:t.key}));let valid=head.ContentLength===t.sizeBytes&&head.ContentLength<MAX&&head.ContentType===t.contentType;let bytes;if(valid){const result=await s3.send(new GetObjectCommand({Bucket:bucket,Key:t.key,Range:'bytes=0-15'}));bytes=Buffer.from(await result.Body.transformToByteArray());valid=magic(bytes,t.contentType);}if(!valid){await s3.send(new DeleteObjectCommand({Bucket:bucket,Key:t.key}));pending.delete(req.body.ticket);return res.status(400).json({error:'El archivo real no coincide con una imagen permitida. Se retiró de la galería.'});}pending.delete(req.body.ticket);res.json({verified:true,key:t.key});});
app.get('/api/images',async(req,res)=>{let token,objects=[];do{const page=await s3.send(new ListObjectsV2Command({Bucket:bucket,Prefix:'originales/',ContinuationToken:token}));objects.push(...(page.Contents||[]));token=page.IsTruncated?page.NextContinuationToken:undefined;}while(token);const images=objects.filter(o=>validKey(o.Key)&&/\\.(jpe?g|png|webp)$/i.test(o.Key)&&o.Size>16&&o.Size<MAX);const items=await Promise.all(images.map(async o=>({key:o.Key,name:o.Key.split('/').pop().replace(/^[0-9a-f-]{36}-/,''),size:o.Size,lastModified:o.LastModified,url:await getSignedUrl(s3,new GetObjectCommand({Bucket:bucket,Key:o.Key}),{expiresIn:900})})));res.json(items.sort((a,b)=>new Date(b.lastModified)-new Date(a.lastModified)));});
app.get('/api/download',async(req,res)=>{if(!validKey(req.query.key))return res.status(400).json({error:'Imagen no válida.'});const name=req.query.key.split('/').pop().replace(/[^a-zA-Z0-9._-]/g,'_');const url=await getSignedUrl(s3,new GetObjectCommand({Bucket:bucket,Key:req.query.key,ResponseContentDisposition:`attachment; filename="${name}"`}),{expiresIn:300});res.json({url});});
app.delete('/api/images/:key',async(req,res)=>{if(!validKey(req.params.key))return res.status(400).json({error:'Imagen no válida.'});await s3.send(new DeleteObjectCommand({Bucket:bucket,Key:req.params.key}));res.json({deleted:true});});
app.use(express.static(root+'public'));
app.use((err,req,res,next)=>{const auth=['CredentialsProviderError','InvalidAccessKeyId','ExpiredToken','InvalidToken','SignatureDoesNotMatch'].includes(err.name);const denied=err.name==='AccessDenied';res.status(auth||denied?503:500).json({error:auth?'No hay credenciales AWS válidas. Configura el perfil local o .env y reinicia.':denied?'AWS rechazó el acceso. Revisa los permisos del perfil sobre este bucket.':'No se pudo completar la operación con S3. Revisa conexión, región y bucket.'});});
app.listen(port,'127.0.0.1',()=>console.log(`Lumen Gallery listo en ${origin}`));
''',encoding='utf8')
(p/'public/index.html').write_text('''<!doctype html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Tu galería privada de imágenes en Amazon S3"><title>Lumen — Tu espacio creativo</title><link rel="stylesheet" href="/styles.css"><script type="module" src="/app.js"></script></head><body><div class="layout"><aside><a class="brand" href="/"><span class="brand-icon">✳</span> lumen<span class="brand-dot">.</span></a><p class="nav-caption">TU ESPACIO CREATIVO</p><nav><button class="nav-link active" id="all-nav"><span data-icon="grid"></span> Mi galería <span id="nav-count">0</span></button><button class="nav-link" id="upload-nav"><span data-icon="upload"></span> Subir imágenes</button></nav><div class="sidebar-art" aria-hidden="true"><div class="orb"></div><span>Ideas que merecen<br>su propio espacio.</span></div><div class="sidebar-bottom"><span class="secure-dot"></span><div><strong>Privado por naturaleza</strong><small>Almacenado en Amazon S3</small></div><span data-icon="lock"></span></div></aside><div class="workspace"><header><div class="breadcrumb">Workspace <span>/</span> Mi galería</div><div class="header-right"><span class="private-badge"><span data-icon="lock"></span> Espacio privado</span><span class="avatar">YL</span></div></header><main><div class="page-title"><div><p class="eyebrow">MENOS LÍMITES. MÁS PERSPECTIVAS.</p><h1>Tu mundo, en imágenes<span>.</span></h1><p>Un lugar para guardar, encontrar y volver a inspirarte.</p></div><button class="primary" id="top-upload"><span data-icon="plus"></span> Subir imágenes</button></div><section class="hero"><div class="hero-copy"><span class="hero-tag">CREA. GUARDA. INSPÍRATE.</span><h2>Grandes ideas.<br>En buenas manos.</h2><p>Tus imágenes, siempre privadas.<br>Tu próxima inspiración, a un clic.</p><span class="hero-bottom"><span data-icon="shield"></span> Cifrado en reposo · Acceso temporal</span></div><div class="hero-visual" aria-hidden="true"><div class="visual-ring"></div><div class="picture picture-back"><div class="landscape moon"></div></div><div class="picture picture-front"><div class="landscape"><div class="sun"></div><div class="mountain mountain-back"></div><div class="mountain"></div></div><div class="picture-caption"><span>Una nueva perspectiva</span><span>✦</span></div></div><div class="float-badge"><span data-icon="lock"></span> Solo para ti</div></div></section><section class="metrics" aria-label="Resumen"><div><span class="metric-icon" data-icon="image"></span><div><strong id="total">0</strong><small>Imágenes en tu galería</small></div></div><div><span class="metric-icon mint" data-icon="cloud"></span><div><strong id="storage">0 KB</strong><small>Espacio utilizado</small></div></div><div><span class="metric-icon peach" data-icon="shield"></span><div><strong>100% privado</strong><small>URLs con acceso temporal</small></div></div></section><section class="dropzone" id="dropzone" aria-label="Carga de imágenes"><div class="upload-symbol" data-icon="upload"></div><div><h3>Arrastra tus mejores momentos aquí</h3><p>JPG, PNG o WebP · Menos de 5 MB por imagen</p></div><button class="secondary" id="choose">Explorar archivos <span data-icon="arrow"></span></button><input id="files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></section><div id="queue" class="queue" aria-live="polite"></div><section class="gallery-section"><div class="gallery-heading"><div><h2>Mi galería <span id="gallery-count">0</span></h2><p>Todo lo que te inspira, en un solo lugar.</p></div><button class="icon-button" id="refresh" aria-label="Actualizar galería"><span data-icon="refresh"></span></button></div><div class="toolbar"><label class="search"><span data-icon="search"></span><input id="search" placeholder="Buscar una imagen…" aria-label="Buscar una imagen"></label><div class="filters" role="group" aria-label="Filtrar por tipo"><button class="selected" data-filter="all">Todas</button><button data-filter="jpg">JPG</button><button data-filter="png">PNG</button><button data-filter="webp">WebP</button></div><label class="sort-label"><select id="sort" aria-label="Ordenar imágenes"><option value="new">Más recientes</option><option value="old">Más antiguas</option><option value="name">Nombre A–Z</option><option value="size">Mayor tamaño</option></select></label></div><div id="connection" class="connection" role="status" hidden></div><div id="gallery" class="gallery" aria-live="polite"></div></section><footer><span><b>lumen.</b> Un espacio para tu mirada.</span><span>Laboratorio 09 · Cloud Storage</span></footer></main></div></div><dialog id="viewer"><div class="viewer-header"><strong id="viewer-title"></strong><button class="icon-button" id="close-viewer" aria-label="Cerrar vista previa">✕</button></div><img id="viewer-image" alt=""><div class="viewer-footer"><span id="viewer-info"></span><button class="primary" id="viewer-download">Descargar imagen</button></div></dialog><dialog id="delete-dialog"><span class="delete-symbol" data-icon="trash"></span><h2>¿Eliminar esta imagen?</h2><p>Se retirará de la galería. Si tu bucket tiene versionado, podrás recuperarla desde la consola de S3.</p><div class="dialog-actions"><button class="secondary" id="cancel-delete">Conservar imagen</button><button class="danger" id="confirm-delete">Eliminar imagen</button></div></dialog><div id="toast" role="status" hidden></div></body></html>''',encoding='utf8')
